/**
 * Local fork (2026-11-16): Z-Moves and Max Moves, the data tables (spec: tools/drive/zmax_1116/design_spec.md).
 * The user: "다이사탕 사용 시 원하는 기술을 다이 기술로 바꿈 / 해당 포켓몬의 전용기는 거다이 기술로 바꿈 (멜메탈: 불릿펀치 ->
 * 다이스틸, 더블펀처 -> 거다이융격) / 전용기가 없는 거다이 포켓몬은 그냥 거다이맥스 기술의 타입 기술이 거다이 기술로 바뀜" and
 * "z 크리스탈 사용 시 해당 타입 기술을 z기술로 변환 / 전용 z 크리스탈은 해당 타입의 기술을 전용 z기술로 변환".
 *
 * GENERATED by tools/drive/zmax_1116/gen_zmax_data.py from zmax_move_table.json and zmax_special_tables.json, which
 * come from Pokemon Showdown's data/moves.ts and sim/dex-moves.ts (MIT License (c) Guangcong Luo and contributors).
 * Do not edit the tables by hand: change the script or its inputs and run `py -I gen_zmax_data.py` again.
 *
 * Power rule (spec 7b): rows whose Showdown value comes from the default rule follow the fork's own base power
 * (`zPowerFromForkPower` / `maxPowerFromForkPower`, e.g. Slash 80 -> Z 160 / Max 130), explicit Showdown values are kept
 * as they are (Double Iron Bash Z 180 / Max 140), the fork's custom moves use the proposed values. Status moves never get
 * a power (Max: Max Guard; Z: the base move plus its Z-Power bonus). A move missing from the table falls back to the
 * Showdown default rule applied to the fork's power and static type.
 *
 * This module imports only enums and types at module level (move.ts, the reward code and move-transform.ts all read it);
 * `allMoves` is only read inside the fallback functions.
 */

import { allMoves } from "#data/data-lists";
import { MoveCategory } from "#enums/move-category";
import { MoveId } from "#enums/move-id";
import { PokemonType } from "#enums/pokemon-type";
import { SpeciesId } from "#enums/species-id";

/** A stat a Z-Power bonus can raise (Showdown's `zMove.boost` keys) */
export type ZBoostStat = "atk" | "def" | "spa" | "spd" | "spe" | "accuracy" | "evasion";

/** The Z-Power bonus of a status move (Showdown's `zMove` field), applied before the move itself */
export type ZStatusEffect =
  | { boost: Partial<Record<ZBoostStat, number>> }
  | { effect: "clearnegativeboost" | "heal" | "crit2" | "healreplacement" | "redirect" | "curse" };

/**
 * Local fork (2026-11-16): every number of the Z / Max rules that is not per-move data (spec sections 0, 2, 6, 7b).
 * Read by move.ts (effects), arena-tag.ts / battler-tags.ts (G-Max fields, Chi Strike) and move-transform.ts.
 */
export const ZMAX_RULES = Object.freeze({
  /** Share of the damage a plain Max / G-Max / Z / exclusive-Z attack deals through Protect-like moves (mainline 1/4) */
  protectPierceMultiplier: 0.25,
  /** Z다이 attacks: "방어/판별 등의 효과를 뚫고 1/2 데미지" (through Max Guard too) */
  zMaxProtectPierceMultiplier: 0.5,
  /** Z다이 attacks: "위력 200 고정" */
  zMaxPower: 200,
  /** 다이검무: "칼춤의 다이기술, 공격 랭크 3업" */
  maxSwordsDanceStages: 3,
  /** Z다이검무: "예외 Z다이검무: 공격 랭크 4업" */
  zMaxSwordsDanceStages: 4,
  /** G-Max Drum Solo / Fireball / Hydrosnipe: fixed power, whatever the base move */
  gmaxFixedPower: 160,
  /** G-Max Wildfire / Vine Lash / Cannonade / Volcalith: turns, and max HP / this lost each turn end (mainline 1/6) */
  gmaxResidualTurns: 4,
  gmaxResidualHpDivisor: 6,
  /** G-Max Steelsurge: Stealth Rock's 1/8, times the Steel type's effectiveness */
  steelsurgeHpRatio: 1 / 8,
  /** G-Max Resonance (Aurora Veil) and G-Max Gravitas (Gravity): turns */
  gmaxResonanceTurns: 5,
  gmaxGravitasTurns: 5,
  /** G-Max Finale: max HP / this healed for the user and its partner (1/6) */
  gmaxFinaleHealDivisor: 6,
  /** G-Max Depletion: PP taken from each foe's last used move */
  gmaxDepletionPp: 2,
  /** G-Max Replenish (per Pokémon) / G-Max Snooze (the target): chance in % */
  gmaxReplenishChance: 50,
  gmaxSnoozeChance: 50,
  /** G-Max Chi Strike: the highest critical-hit stage it builds up to (+1 per hit) */
  gmaxChiStrikeMaxStages: 3,
  /** Guardian of Alola: share of the target's current HP it takes */
  guardianOfAlolaHpRatio: 3 / 4,
  /** 10,000,000 Volt Thunderbolt: extra critical-hit stages */
  tenMillionVoltCritStages: 2,
});

