const POWER_TABLE: ReadonlyMap<MoveId, readonly [number, number]> = new Map(
  POWER_ROWS.map(([id, z, max]) => [id, Object.freeze([z, max] as const)]),
);

const Z_STATUS_TABLE: ReadonlyMap<MoveId, ZStatusEffect | null> = new Map(
  Z_STATUS_ROWS.map(([id, effect]) => [id, effect == null ? null : Object.freeze(effect)]),
);

/**
 * Showdown's default Max power (`sim/dex-moves.ts`): 0 or variable power -> 100; Fighting and Poison use the low table.
 * @param power - The base power (`<= 0` for variable / fixed damage moves)
 * @param type - The move's static type
 */
function defaultMaxPower(power: number, type: PokemonType): number {
  if (power <= 0) {
    return 100;
  }
  const low = type === PokemonType.FIGHTING || type === PokemonType.POISON;
  const steps: readonly (readonly [number, number, number])[] = [
    [150, 100, 150],
    [110, 95, 140],
    [75, 90, 130],
    [65, 85, 120],
    [55, 80, 110],
    [45, 75, 100],
  ];
  for (const [min, lowPower, highPower] of steps) {
    if (power >= min) {
      return low ? lowPower : highPower;
    }
  }
  return low ? 70 : 90;
}

/**
 * Showdown's default Z power (`sim/dex-moves.ts`, without its x3 for random-count multi-hit moves, which only matters
 * for moves the table already lists).
 * @param power - The base power (`<= 0` for variable / fixed damage moves)
 */
function defaultZPower(power: number): number {
  if (power <= 0) {
    return 100;
  }
  const steps: readonly (readonly [number, number])[] = [
    [140, 200],
    [130, 195],
    [120, 190],
    [110, 185],
    [100, 180],
    [90, 175],
    [80, 160],
    [70, 140],
    [60, 120],
  ];
  for (const [min, z] of steps) {
    if (power >= min) {
      return z;
    }
  }
  return 100;
}

/**
 * Local fork (2026-11-16): the power of the Max (or G-Max, except the three fixed 160 ones) move made from `baseId`.
 * @param baseId - The slot's original move
 * @returns The table value, else Showdown's default rule from the fork's power and static type; `0` for a move with no
 * Max power (status moves become Max Guard, Struggle has none)
 */
export function getMaxMovePower(baseId: MoveId): number {
  const row = POWER_TABLE.get(baseId);
  if (row) {
    return row[1];
  }
  const move = allMoves[baseId];
  if (!move || move.category === MoveCategory.STATUS || baseId === MoveId.STRUGGLE) {
    return 0;
  }
  return defaultMaxPower(move.power, move.type);
}

/**
 * Local fork (2026-11-16): the power of the type Z-Move made from `baseId`.
 * @param baseId - The slot's original move
 * @returns The table value, else Showdown's default rule from the fork's power; `0` for a status move or Struggle
 */
export function getZMovePower(baseId: MoveId): number {
  const row = POWER_TABLE.get(baseId);
  if (row) {
    return row[0];
  }
  const move = allMoves[baseId];
  if (!move || move.category === MoveCategory.STATUS || baseId === MoveId.STRUGGLE) {
    return 0;
  }
  return defaultZPower(move.power);
}

/**
 * Local fork (2026-11-16): the Z-Power bonus a status move gets as a Z-Move ("Z칼춤": Swords Dance resets the user's
 * lowered stats, then raises its Attack by 2 as usual).
 * @param baseId - The slot's original move
 * @returns The bonus, or `null` if the move has none (or is not a status move)
 */
export function getZStatusEffect(baseId: MoveId): ZStatusEffect | null {
  return Z_STATUS_TABLE.get(baseId) ?? null;
}

